//! ↩️ move-texture leaf-owned inverse reconstruction from exact base values.
use serde::{Deserialize, Serialize};
use crate::artifacts::gltf::GltfSnapshot;
use crate::artifacts::gltf::schema::snapshot::GltfTexture;
use crate::artifacts::gltf::schema::mutations::move_texture::mutation::{validate, GltfMoveTexturePayload};
use crate::artifacts::gltf::schema::mutations::top_level_collections_private::{textures_op, reject, repair, Change, GltfTopLevelFamily, GltfTopLevelMutationRejection};
pub const ID: &str = "s.stdio.gltf.mutation.move-texture.v1.inverse";
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(tag = "kind", rename_all = "camelCase")]
pub enum GltfMoveTextureInverseOperation { Insert { position: usize, item: GltfTexture }, Delete { index: usize, removed: GltfTexture }, Move { index: usize, position: usize }, Reorder { order: Vec<usize> } }
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(rename_all = "camelCase")]
pub struct GltfMoveTextureInverse { pub id: String, pub version: u32, pub touched_paths: Vec<String>, pub payload: GltfMoveTexturePayload, pub operation: GltfMoveTextureInverseOperation }
fn operation(payload: &GltfMoveTexturePayload, base: &GltfSnapshot) -> GltfMoveTextureInverseOperation { GltfMoveTextureInverseOperation::Move { index: payload.position, position: payload.index } }
fn touched_paths(payload: &GltfMoveTexturePayload) -> Vec<String> { vec![format!("document/textures/{}", payload.index), format!("document/textures/{}", payload.position)] }
pub fn validate_inverse(inverse: &GltfMoveTextureInverse) -> Result<(), GltfTopLevelMutationRejection> { if inverse.id != ID || inverse.version != 1 { return Err(reject("gltf.mutation.invalid-inverse-envelope", "inverse", "descriptor identity does not match")); } if inverse.touched_paths != touched_paths(&inverse.payload) { return Err(reject("gltf.mutation.invalid-touched-paths", "inverse/touchedPaths", "paths must be concrete payload-derived locations")); } Ok(()) }
pub fn apply_inverse(inverse: &GltfMoveTextureInverse, after: &GltfSnapshot) -> Result<GltfSnapshot, GltfTopLevelMutationRejection> { validate_inverse(inverse)?; let operation = &inverse.operation; match operation { GltfMoveTextureInverseOperation::Insert { position, .. } if *position > after.document.textures.len() => return Err(reject("gltf.mutation.insert-out-of-range", "document/textures", "position must be within the collection")), GltfMoveTextureInverseOperation::Delete { index, .. } if *index >= after.document.textures.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/textures", "index must address an item")), GltfMoveTextureInverseOperation::Move { index, position } if *index >= after.document.textures.len() || *position >= after.document.textures.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/textures", "indices must address items")), GltfMoveTextureInverseOperation::Reorder { order } if order.is_empty() || order.len() != after.document.textures.len() || order.iter().collect::<std::collections::BTreeSet<_>>().len() != order.len() || order.iter().any(|index| *index >= after.document.textures.len()) => return Err(reject("gltf.mutation.invalid-permutation", "document/textures", "order must be a non-empty permutation")), _ => {} } let mut next = after.clone(); match operation { GltfMoveTextureInverseOperation::Insert { position, item } => { repair(&mut next.document, GltfTopLevelFamily::Textures, &Change::Insert(*position))?; next.document.textures.insert(*position, item.clone());  }, GltfMoveTextureInverseOperation::Delete { index, .. } => { textures_op(&mut next, GltfTopLevelFamily::Textures, *index, None, None)?;  }, GltfMoveTextureInverseOperation::Move { index, position } => { textures_op(&mut next, GltfTopLevelFamily::Textures, *index, Some(*position), None)?;  }, GltfMoveTextureInverseOperation::Reorder { order } => { textures_op(&mut next, GltfTopLevelFamily::Textures, order[0], None, Some(order))?;  } } Ok(next) }
pub fn encode(inverse: &GltfMoveTextureInverse) -> Result<Vec<u8>, GltfTopLevelMutationRejection> { serde_json::to_vec(inverse).map_err(|error| reject("gltf.mutation.encode-failed", "inverse", error.to_string())) }
pub fn derive(payload: &GltfMoveTexturePayload, base: &GltfSnapshot) -> Result<GltfMoveTextureInverse, GltfTopLevelMutationRejection> { validate(payload, base)?; Ok(GltfMoveTextureInverse { id: ID.into(), version: 1, touched_paths: touched_paths(payload), payload: payload.clone(), operation: operation(payload, base) }) }
